 name=mod.split('.')[-1];q=base/'lib/DiophantineConsistency'/(name+'.olean');z=v['observed'][name];assert str(q.resolve())==z['realpath'] and sha(q)==z['sha256'] and state['overlay_links'][str(q)]==z['realpath']
